/* The letter typeface, inlined as data URIs for the same reason as the wordmark: a font file that
   isn't in the serverless bundle fails only in production.

   Tinos (Steve Matteson, SIL Open Font License 1.1; see OFL-Tinos.txt), which has the same widths as
   Times, so letters set as they did in the PDF base font. The base font has no rupee sign: it printed
   a superscript 1 over the first digit of every amount. Unhinted subset of Latin, Greek, punctuation
   and currency signs, renamed as the licence expects of a modified font. No bold italic. */

export const LETTER_SERIF_REGULAR =
  'data:font/ttf;base64,'

export const LETTER_SERIF_BOLD =
  'data:font/ttf;base64,'

export const LETTER_SERIF_ITALIC =
  'data:font/ttf;base64,'
